import ipaddress
import socket
import pytest

original_getaddrinfo = socket.getaddrinfo
original_connect = socket.socket.connect
original_connect_ex = socket.socket.connect_ex

def check_host(host):
    if isinstance(host, bytes):
        host = host.decode('ascii')
    if host in (None, '', 'localhost'):
        return
    try:
        local = ipaddress.ip_address(host).is_loopback
    except ValueError:
        local = False
    if not local:
        raise AssertionError(f'Non-loopback network access blocked: {host}')

def getaddrinfo(host, *args, **kwargs):
    check_host(host)
    return original_getaddrinfo(host, *args, **kwargs)

def connect(sock, address):
    if sock.family in (socket.AF_INET, socket.AF_INET6):
        check_host(address[0])
    return original_connect(sock, address)

def connect_ex(sock, address):
    if sock.family in (socket.AF_INET, socket.AF_INET6):
        check_host(address[0])
    return original_connect_ex(sock, address)

socket.getaddrinfo = getaddrinfo
socket.socket.connect = connect
socket.socket.connect_ex = connect_ex
raise SystemExit(pytest.main(['-q', 'tests/test_requests.py', 'tests/test_lowlevel.py', 'tests/test_hooks.py', 'tests/test_adapters.py', '-k', 'content or iter or stream or pickle or hook or redirect or gzip or chunked or requests_are_updated', '--tb=short']))
